def summarize_tasks(tasks: list[dict], status=None) -> dict:
    if status is None:
        return {
            "count": len(tasks),
            "total_duration": sum(task["duration"] for task in tasks),
        }

    matched = [task for task in tasks if task["status"] == status]
    return {
        "count": len(matched),
        "total_duration": sum(task["duration"] for task in matched),
    }
